CREATE TABLE stock_count_lines (
  id                    TEXT PRIMARY KEY,
  session_id            TEXT NOT NULL REFERENCES stock_count_sessions(id) DEFERRABLE INITIALLY IMMEDIATE,
  product_id            TEXT NOT NULL REFERENCES products(id) DEFERRABLE INITIALLY IMMEDIATE,
  system_qty_snapshot   NUMERIC NOT NULL,
  counted_qty           NUMERIC CHECK (counted_qty IS NULL OR counted_qty >= 0),
  updated_at            TEXT NOT NULL DEFAULT (sqlite_datetime('now')), reason_code TEXT NULL
  CHECK (reason_code IS NULL OR reason_code IN ('damaged', 'expired', 'stolen_lost', 'admin_error')), unit_cost_paisa_snapshot BIGINT NULL,
  UNIQUE (session_id, product_id)
,
  rowid BIGINT GENERATED BY DEFAULT AS IDENTITY
);

CREATE TABLE stock_adjustments (
  id            TEXT PRIMARY KEY,
  product_id    TEXT NOT NULL REFERENCES products(id) DEFERRABLE INITIALLY IMMEDIATE,
  session_id    TEXT REFERENCES stock_count_sessions(id) DEFERRABLE INITIALLY IMMEDIATE,
  line_id       TEXT REFERENCES stock_count_lines(id) DEFERRABLE INITIALLY IMMEDIATE,
  delta_pieces  NUMERIC NOT NULL,
  qty_before    NUMERIC NOT NULL,
  qty_after     NUMERIC NOT NULL,
  reason        TEXT NOT NULL DEFAULT 'stock_count',
  created_by    TEXT NOT NULL REFERENCES users(id) DEFERRABLE INITIALLY IMMEDIATE,
  created_at    TEXT NOT NULL DEFAULT (sqlite_datetime('now')),
  note          TEXT, reason_code TEXT NULL
  CHECK (reason_code IS NULL OR reason_code IN ('damaged', 'expired', 'stolen_lost', 'admin_error')), unit_cost_paisa BIGINT NULL,
  CHECK (delta_pieces != 0),
  CHECK (qty_after >= 0)
,
  rowid BIGINT GENERATED BY DEFAULT AS IDENTITY
);

CREATE TABLE stock_balances (
  product_id   TEXT PRIMARY KEY REFERENCES products(id) DEFERRABLE INITIALLY IMMEDIATE,
  qty_on_hand  NUMERIC NOT NULL DEFAULT 0 CHECK (qty_on_hand >= 0),
  updated_at   TEXT NOT NULL DEFAULT (sqlite_datetime('now'))
,
  rowid BIGINT GENERATED BY DEFAULT AS IDENTITY
);

CREATE TABLE stock_receives (
  id            TEXT PRIMARY KEY,
  product_id    TEXT NOT NULL REFERENCES products(id) DEFERRABLE INITIALLY IMMEDIATE,
  qty_input     NUMERIC NOT NULL CHECK (qty_input > 0),
  unit          TEXT NOT NULL CHECK (unit IN ('piece', 'carton')),
  qty_pieces    NUMERIC NOT NULL CHECK (qty_pieces > 0),
  received_by   TEXT REFERENCES users(id) DEFERRABLE INITIALLY IMMEDIATE,
  note          TEXT,
  created_at    TEXT NOT NULL DEFAULT (sqlite_datetime('now'))
, amount_paisa BIGINT, unit_cost_paisa BIGINT, supplier_id TEXT REFERENCES suppliers(id) DEFERRABLE INITIALLY IMMEDIATE, paid_now BIGINT NOT NULL DEFAULT 0, purchase_invoice_id TEXT REFERENCES purchase_invoices(id) DEFERRABLE INITIALLY IMMEDIATE,
  rowid BIGINT GENERATED BY DEFAULT AS IDENTITY
);

CREATE TABLE supplier_payments (
  id            TEXT PRIMARY KEY,
  supplier_id   TEXT NOT NULL REFERENCES suppliers(id) DEFERRABLE INITIALLY IMMEDIATE,
  amount_paisa  BIGINT NOT NULL CHECK (amount_paisa > 0),
  paid_on       TEXT NOT NULL,
  note          TEXT,
  created_at    TEXT NOT NULL DEFAULT (sqlite_datetime('now'))
,
  rowid BIGINT GENERATED BY DEFAULT AS IDENTITY
);

CREATE TABLE supplier_product_pack (
  supplier_id     TEXT NOT NULL REFERENCES suppliers(id) DEFERRABLE INITIALLY IMMEDIATE,
  product_id      TEXT NOT NULL REFERENCES products(id) DEFERRABLE INITIALLY IMMEDIATE,
  pack_id         TEXT REFERENCES product_packs(id) DEFERRABLE INITIALLY IMMEDIATE,
  pack_units      DOUBLE PRECISION,
  last_cost_paisa BIGINT,
  updated_at      TEXT NOT NULL DEFAULT (sqlite_datetime('now')),
  PRIMARY KEY (supplier_id, product_id)
,
  rowid BIGINT GENERATED BY DEFAULT AS IDENTITY
);

CREATE TABLE supplier_returns (
  id           TEXT PRIMARY KEY,
  short_id     TEXT NOT NULL,
  supplier_id  TEXT NOT NULL REFERENCES suppliers(id) DEFERRABLE INITIALLY IMMEDIATE,
  total_paisa  BIGINT NOT NULL CHECK (total_paisa > 0),
  note         TEXT,
  returned_on  TEXT NOT NULL,
  created_by   TEXT REFERENCES users(id) DEFERRABLE INITIALLY IMMEDIATE,
  created_at   TEXT NOT NULL
,
  rowid BIGINT GENERATED BY DEFAULT AS IDENTITY
);

CREATE TABLE supplier_return_lines (
  id               TEXT PRIMARY KEY,
  return_id        TEXT NOT NULL REFERENCES supplier_returns(id) ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE,
  product_id       TEXT NOT NULL REFERENCES products(id) DEFERRABLE INITIALLY IMMEDIATE,
  product_name     TEXT NOT NULL,
  qty              DOUBLE PRECISION NOT NULL CHECK (qty > 0),
  unit_cost_paisa  BIGINT NOT NULL CHECK (unit_cost_paisa >= 0),
  line_total_paisa BIGINT NOT NULL CHECK (line_total_paisa >= 0)
,
  rowid BIGINT GENERATED BY DEFAULT AS IDENTITY
);

CREATE TABLE "tax_documents" (
  id              TEXT PRIMARY KEY,
  sale_id         TEXT,
  status          TEXT NOT NULL DEFAULT 'queued'
                    CHECK (status IN (
                      'queued',
                      'submitting',
                      'accepted',
                      'rejected',
                      'authority_down',
                      'credit_note_queued',
                      'voided'
                    )),
  payload_json    TEXT NOT NULL DEFAULT '{}',
  provider_ref    TEXT,
  reason_stub     TEXT,
  raw_detail      TEXT,
  disposition     TEXT
                    CHECK (
                      disposition IS NULL
                      OR disposition IN ('void', 'keep_flag', 'credit_note')
                    ),
  disposed_at     TEXT,
  disposed_by     TEXT,
  client_device_at TEXT NOT NULL,
  created_at      TEXT NOT NULL DEFAULT (sqlite_datetime('now')),
  updated_at      TEXT NOT NULL DEFAULT (sqlite_datetime('now'))
,
  rowid BIGINT GENERATED BY DEFAULT AS IDENTITY
);

CREATE TABLE till_shifts (
  id                   TEXT PRIMARY KEY,
  opened_at            TEXT NOT NULL,
  opened_by            TEXT REFERENCES users(id) DEFERRABLE INITIALLY IMMEDIATE,
  opening_float_paisa  BIGINT NOT NULL DEFAULT 0 CHECK (opening_float_paisa >= 0),
  closed_at            TEXT,
  closed_by            TEXT REFERENCES users(id) DEFERRABLE INITIALLY IMMEDIATE,
  expected_paisa       BIGINT,
  counted_paisa        BIGINT,
  over_short_paisa     BIGINT,
  summary_json         TEXT,
  note                 TEXT
,
  rowid BIGINT GENERATED BY DEFAULT AS IDENTITY
);

CREATE TABLE till_moves (
  id            TEXT PRIMARY KEY,
  shift_id      TEXT NOT NULL REFERENCES till_shifts(id) ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE,
  kind          TEXT NOT NULL CHECK (kind IN ('in', 'out')),
  amount_paisa  BIGINT NOT NULL CHECK (amount_paisa > 0),
  reason        TEXT,
  created_by    TEXT REFERENCES users(id) DEFERRABLE INITIALLY IMMEDIATE,
  created_at    TEXT NOT NULL
,
  rowid BIGINT GENERATED BY DEFAULT AS IDENTITY
);

